import 'package:flutter/material.dart';

/// نقش‌های برداری فروهر و آدم بال‌دار هخامنشی برای صفحه‌ی تخته‌نرد.
/// داده‌ها از روی تصویرهای مرجع به‌صورت چندضلعی (مختصات ۰ تا ۱۰۰۰) ردیابی شده‌اند؛
/// با پر کردن even-odd و منحنی‌های هموار رسم می‌شوند، پس در هر اندازه تیز می‌مانند.

enum BgSymbol { faravahar, wingedMan }

Path _buildSymbolPath(List<List<int>> polys) {
  final path = Path()..fillType = PathFillType.evenOdd;
  for (final p in polys) {
    final n = p.length ~/ 2;
    if (n < 3) continue;
    Offset pt(int i) => Offset(p[2 * (i % n)].toDouble(), p[2 * (i % n) + 1].toDouble());
    Offset mid(Offset a, Offset b) => Offset((a.dx + b.dx) / 2, (a.dy + b.dy) / 2);
    final m0 = mid(pt(0), pt(1));
    path.moveTo(m0.dx, m0.dy);
    for (var i = 1; i <= n; i++) {
      final m = mid(pt(i), pt(i + 1));
      path.quadraticBezierTo(pt(i).dx, pt(i).dy, m.dx, m.dy);
    }
    path.close();
  }
  return path;
}

Path? _farPath;
Path? _manPath;

/// نقش را وسط [center] می‌کشد؛ [extent] = عرض فروهر یا ارتفاع آدم بال‌دار (به پیکسل).
void paintBgSymbol(Canvas canvas, BgSymbol s, Offset center, double extent, Color color) {
  final far = s == BgSymbol.faravahar;
  final path = far ? (_farPath ??= _buildSymbolPath(kFaravaharPolys)) : (_manPath ??= _buildSymbolPath(kWingedManPolys));
  final w = (far ? kFaravaharW : kWingedManW).toDouble();
  final h = (far ? kFaravaharH : kWingedManH).toDouble();
  final k = extent / (far ? w : h);
  canvas.save();
  canvas.translate(center.dx - w * k / 2, center.dy - h * k / 2);
  canvas.scale(k, k);
  canvas.drawPath(path, Paint()..color = color..isAntiAlias = true);
  canvas.restore();
}

